mapper.delete:
    	DELETE FROM PBC_CAPITAL_TRUST_DETAIL_SUB WHERE REPORTUUID IN (
    	 SELECT REPORTUUID from PBC_REPORT
	   where 1=1

	   	and to_char(startdate,'yyyy-MM-dd') >= to_char(#{startdate,jdbcType=DATE},'yyyy-MM-dd')


	   	and to_char(enddate,'yyyy-MM-dd') >= to_char(#{enddate,jdbcType=DATE},'yyyy-MM-dd')


	   	and REPORTTYPE = #{reporttype,jdbcType=VARCHAR}


	   	and REPORTFREQU = #{reportfrequ,jdbcType=VARCHAR}


	   	and PBC_ACCOUNT_ID = #{pbcAccountId,jdbcType=VARCHAR}


         and PBC_ACCOUNT_ID is null

        and send_status = '01'/*只删除未报送数据*/

    	)
